INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HARTMANN MOLICARE MOBILE SLIP ABSORBANT TAILLE L/JOUR X14 REF:166015','Hartmann','Bébé & Maman','Un triple coussin absorbant constitué de cellulose défibrée, de super absorbant et d’un coussin diffuseur garantissant une diffusion rapide des urines et un effet garde au sec.
