INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Janssen Cosmetics Roll-On Yeux Energisant 15ml','Janssen Cosmetics','Visage','Une énergie et une fraîcheur renouvelées pour le contour des yeux fatigués : avec son effet rafraîchissant immédiat, le puissant complexe d’actifs 4-en-1 revitalise la peau, réduit visiblement les gonflements et estompe les cernes foncés. Les rides et ridules sont rapidement atténuées.

