INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Soulsisters Crème de Jour SPF 25 — 100ml','SoulSisters','Solaires','Une crème de jour SPF 25 légère et invisible qui offre une hydratation en profondeur et protège la peau contre les agressions environnementales, les UVA, UVB, la lumière bleue et la pollution. Contient une protection SPF 25 et de la Niacinamide pour un soutien quotidien de la barrière cutanée.

