INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOURKRIN WOMAN 60 TABLETTES','Nourkrin','Cheveux','Redonnez vie à vos cheveux avec Nourkrin Woman 60 Tablets, une solution scientifiquement élaborée pour soutenir la santé de vos follicules pileux. Ce complément alimentaire unique utilise les protéoglycanes bioactifs, alliés au complexe breveté Marilex, pour agir directement sur le cycle naturel de croissance des cheveux.

