INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Q+A  Sérum Booster de Collagène 15ml','Q+A','Visage','Saviez-vous que le collagène peut être naturellement dérivé des légumes ? La formule végétarienne unique de notre Crème Collagène prévient les rides et aide à améliorer la fermeté, la souplesse et l''élasticité de la peau.',15000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Q_ACOLLAGENSERUM.jpg?v=1733760840',10,1,'8128920977583','44708376707247','https://beautymarket.ma/products/q-a-serum-booster-de-collagene-15ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Q_ACOLLAGENSERUM.jpg?v=1733760840"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
