INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ZIAJA CREME MAINS REPARATRICE HUILE D''ARGAN 100 ML','Ziaja','Maquillage','Crème protectrice pour les mains à l''huile d''argan naturelle et à la glycérine pour les peaux sèches et irritées. Renforce la barrière cutanée hydrolipidique. Apaise les rougeurs de l''épiderme. Soulage la peau trop sèche en la laissant douce et lisse. Augmente l''hydratation de la peau de 39%*. Absorbe rapidement.
*Les résultats prouvés lors de tests in vivo.

Conseils d''utilisation:
Appliquer sur une peau propre et masser doucement.',6200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-ziaja-creme-mains-reparatrice-huile-dargan-100-ml-mains.jpg?v=1734973297',10,1,'8136107393199','44753986093231','https://beautymarket.ma/products/ziaja-creme-mains-reparatrice-huile-dargan-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ziaja-ziaja-creme-mains-reparatrice-huile-dargan-100-ml-mains.jpg?v=1734973297"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEXIDENT BAIN DE BOUCHE FRAICHEUR 500 ML','Isdin','Hygiène','Bain de bouche  c''est un rince-bouche formulé pour être utilisé tous les jours, car il préserve l''haleine fraîche jusqu''à 24 heures après utilisation, bloquant les substances et les processus qui causent l''halitose.Il a une composition qui réduit la bouche sèche, car il comprend la technologie de neutralisation VSC qui élimine les bactéries et empêche le dépôt de composés soufrés instables qui génèrent une mauvaise haleine.',8900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident-bain-de-bouche-fraicheur-500ml.jpg?v=1734973564',10,1,'8136108212399','44753994154159','https://beautymarket.ma/products/bexident-bain-de-bouche-fraicheur-500-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident-bain-de-bouche-fraicheur-500ml.jpg?v=1734973564"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDIN BEXIDENT ANTICARIES BAIN DE BOUCHE 500ml','Isdin','Hygiène','ISDIN BEXIDENT ANTICARIES BAIN DE BOUCHE
Une hygiène bucco-dentaire insuffisante entraîne une colonisation bactérienne des dents. Les bactéries produisent des acides qui dissolvent graduellement l’émail et causent des infections dans la bouche.

Le bain de bouche Bexident anti-caries est un rince-bouche quotidien à triple action :

Des antiquités.
Antiseptique.
Anti-plaque
Pourcentage de lutte contre les caries grâce à son association de fluorure de sodium et d’extrait de canneberge. De plus, il empêche l’adhérence des bactéries sur les dents, empêchant ainsi la formation de plaque bacérienne.',6500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ISDIN-BEXIDENT-ANTICARIES-BAIN-DE-BOUCHE-500mL.jpg?v=1734974070',10,1,'8136110112943','44754011881647','https://beautymarket.ma/products/isdin-bexident-anticaries-bain-de-bouche-500ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ISDIN-BEXIDENT-ANTICARIES-BAIN-DE-BOUCHE-500mL.jpg?v=1734974070"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEXIDENT DENTIFRICE GEL GINGIVAL 0,12 75 ML','Isdin','Hygiène','Dentifrice Gel Gingival Bexident Treatment il est recommandé pour l''hygiène bucco-dentaire quotidienne des gencives fragiles sous traitement dentaire, ou en cas de pose d''implant, de chirurgie parodontale ou maxillo-faciale.Gel dentifrice à la chlorhexidine 0,12% Aide à prévenir la formation de biofilm et de plaque.

Mode d''emploi:

Brossez-vous deux ou trois fois par jour, après les repas, pendant deux ou trois minutes. Ne pas ingérer.',5500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident-bexident-dentifrice-gel-gingival-012-75-ml-dentifrices-gencives-sensibles.jpg?v=1734974729',10,1,'8136111882415','44754021384367','https://beautymarket.ma/products/bexident-dentifrice-gel-gingival-0-12-75-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bexident-bexident-dentifrice-gel-gingival-012-75-ml-dentifrices-gencives-sensibles.jpg?v=1734974729"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bexident dentifrices gencives Daily use 75ml','Isdin','Hygiène','Dentifrice Bexident Gum 75 ml est une gamme de produits à usage quotidien (dentifrice et bain de bouche) et de soin (gel et bain de bouche en spray) pour le traitement des gencives sensibles.',5300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8429420184923.jpg?v=1734975168',10,1,'8136113488047','44754033017007','https://beautymarket.ma/products/bexident-dentifrices-gencives-daily-use-75ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8429420184923.jpg?v=1734975168"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bexident dentifrices dents sensibles 75ml','Isdin','Hygiène','Le dentifrice dents sensibles Bexident est formulé avec des ingrédients qui réduisent la sensibilité (nitrate de potassium), favorisent la minéralisation de l’émail (fluorure de sodium) et anti-plaque qui réduisent les douleurs dentaires et ont des gencives saines et protégées. Grâce à son excipient bioadhésif, son action est prolongée dans le temps. Tous les produits Bexident Dents Sensibles, bien que contenant du nitrate de potassium, ont un goût agréable pour assurer une utilisation à long terme.',5500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8429420184954.jpg?v=1734976327',10,1,'8136117518511','44754065850543','https://beautymarket.ma/products/bexident-dentifrices-dents-sensibles-75ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8429420184954.jpg?v=1734976327"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURASEPT BAIN DE BOUCHE DNA IMPLANT PRO 200ML','Curasept','Hygiène','Ne tache pas, sans alcool, 0,2 % de chlorhexidine avec ADN et acide hyaluronique.
Curasept Implant Pro est un bain de bouche antiseptique permettant de réparer rapidement et efficacement le tissu muqueux et de maximiser le processus de guérison. À utiliser avant et après une intervention chirurgicale, avant et après la pose d''implants, après des procédures de régénération et d''augmentation osseuses et après des opérations parodontales ou péri-implantaires ; forme un film protecteur sur les gencives et favorise la régénération. Appareil cosmétique.

COMPOSITION :

Eau purifiée, xylitol, acide hyaluronique, propylène glycol, huile de ricin hydrogénée Peg-40, acide ascorbique, digluconate de chlorhexidine (0,2 %), arôme, poloxamer 407, métabisulfite de sodium, citrate de sodium, Ci42090.',8600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-ads-dna-implant-pro-200-ml-bains-de-bouche_ac6598a7-df22-4963-b89b-04b158eddae4.jpg?v=1735033393',10,1,'8136320843951','44755782860975','https://beautymarket.ma/products/curasept-ads-dna-implant-pro-200-ml-1',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-ads-dna-implant-pro-200-ml-bains-de-bouche_ac6598a7-df22-4963-b89b-04b158eddae4.jpg?v=1735033393"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dodie Accessoire Bouillotte Graines +6m Eléphant','Dodie','Bébé & Maman','Dodie vous propose une bouillotte Peluche Éléphant , pour une pure sensation de chaleur adaptée aux enfants de 6 mois et plus . Son utilisation à chaud va permettre de soulager les maux de ventre de bébé. Elle va aussi pouvoir soulager les coliques, réchauffer le lit, soigner les chagrins. Sa petite taille va pouvoir s''adapter au petit gabarit de l''enfant.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pdt2_4_8_6_3_700x700_pol3700763503486_rw_dodie-accessoire-bouillotte-graines-6m-elephant.jpg?v=1735033978',10,1,'8136322580655','44755788103855','https://beautymarket.ma/products/dodie-accessoire-bouillotte-graines-6m-elephant',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pdt2_4_8_6_3_700x700_pol3700763503486_rw_dodie-accessoire-bouillotte-graines-6m-elephant.jpg?v=1735033978","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pdt2_4_8_6_1_700x700_pol3700763503486_rw_dodie-accessoire-bouillotte-graines-6m-elephant.jpg?v=1735033978","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pdt2_4_8_6_4_700x700_pol3700763503486_rw_dodie-accessoire-bouillotte-graines-6m-elephant.jpg?v=1735033978"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CURASEPT BAIN DE BOUCHE DNA PERIO PRO 500ML','Curasept','Hygiène','Curasept ADS Perio Pro Oral Rinse 0,12% Chlorhexidine avec acide hyaluronique et ADN.

Curasept ADS Perio Pro Oral Rinse a été développé pour cibler spécifiquement les besoins de traitement des patients souffrant de gingivite, de parodontite et de péri-implantite, ainsi que pour soutenir les résultats cliniques du surfaçage radiculaire, de la chirurgie au laser et des ébauches gingivales.

Avec 0,12 % de chlorhexidine pour une forte action antibactérienne et anti-plaque, ainsi que de l''acide hyaluronique et de l''ADN de sodium pour réduire l''inflammation, apaiser les irritations et stimuler le processus de guérison, c''est une solution idéale pour les soins de rééducation prolongés et très efficaces des gencive rouge, enflammée et saignante.

Grâce à une formule unique et brevetée, son système anti-décoloration (ADS) réduit également considérablement la décoloration des dents et les perturbations du goût, tandis que son flacon de 500 ml permet aux patients de bénéficier d''un plan de traitement complet de 4 semaines en une seule fois.

Sans alcool et sans SLS.

CONSEILS D''UTILISATION:

Rincer pendant une minute avec 10 ml de solution non diluée. Ne rincez pas ensuite.
Utiliser deux fois par jour pendant 4 semaines maximum.',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-ads-dna-perio-pro-500-ml-bains-de-bouche.jpg?v=1735034031',10,1,'8136322810031','44755788431535','https://beautymarket.ma/products/curasept-ads-dna-perio-pro-500-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/curasept-curasept-ads-dna-perio-pro-500-ml-bains-de-bouche.jpg?v=1735034031"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
