INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NIVEA MEN CRÈME DE SOIN HYDRATANTE 75 ML','Nivea','Visage','Prenez soin de votre peau avec la crème NIVEA MEN, une crème hydratante qui revitalise et protège. Sa formule légère et non grasse pénètre rapidement, laissant votre peau douce et nourrie. Appliquez-la sur le visage, le corps et les mains pour une hydratation instantanée et une sensation de confort toute la journée.

