INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Sensilis Gentle Cleansing Mousse 200ml – Mousse Nettoyante Douce & Apaisante pour Peaux Sensibles','Sensilis','Visage','Sensilis Gentle Cleansing Mousse 200ml

