INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SO BIO DEODORANT SPRAY AMANDE 100ML','So Bio','Corps','Le Déo-Soin Spray à l''Amande :

