INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SO BIO MEN GEL ALOE VERA APRES RASAGE 100 ML','So Bio','Visage','Hautement concentré en jus d''Aloe vera bio équitable, ce Soin après-rasage 3-en-1 à la texture fraîche apaise le feu du rasoir, hydrate1 intensément et procure une agréable sensation de fraîcheur. Absorption rapide. Convient aux peaux sensibles.

Testé sous contrôle dermatologique.

COMPOSITION :

Aqua/Water/Eau : Eau purifiée
Aloe Barbadensis Leaf Juice* : Pur jus d’Aloe vera bio équitable du Mexique
Glycerin : Humectant d’origine naturelle
Caprylic/Capric Triglyceride, Coco-Caprylate/Caprate : Emollients d’origine naturelle
Pentylene Glycol : Humectant d’origine naturelle
Inulin : Actif rééquilibrant1 d’origine naturelle
Kaolin : Argile blanche absorbante1
Acacia Decurrens/Jojoba/Sunflower Seed Wax Polyglyceryl-3 Esters : Association de cires végétales hydratante
Microcrystalline Cellulose, Sclerotium Gum, Xanthan Gum, Chondrus Crispus (Carrageenan) Extract, Cellulose : Gélifiants d’origine naturelle
Cellulose Gum : Gélifiant d’origine naturelle et synthétique
Cetearyl Olivate, Sorbitan Olivate : Emulsionnants d’origine naturelle
Fructose, Glucose : Sucres stabilisants d’origine naturelle
Sodium Levulinate, Levulinic Acid : Stabilisant d’origine naturelle
Parfum (Fragrance) : Parfum 100% d’origine naturelle
Benzyl Alcohol : Conservateur d’origine synthétique
Sodium Hydroxide, Citric Acid : Ajusteurs de pH d’origine naturelle
Limonene, Linalool, Citronellol : Allergènes naturels issus des plantes, présents dans la composition parfumée 100% d’origine naturelle

CONSEILS D''UTILISATION :

Appliquez sur la peau après le rasage.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/so-bio-so-bio-men-gel-aloe-vera-apres-rasage-100-ml-rasage-et-barbe.jpg?v=1736182559',10,1,'8140382666927','44791209394351','https://beautymarket.ma/products/so-bio-men-gel-aloe-vera-apres-rasage-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/so-bio-so-bio-men-gel-aloe-vera-apres-rasage-100-ml-rasage-et-barbe.jpg?v=1736182559"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SO BIO GEL INTIME FLEUR DE MAUVE HYPOALLERGENIQUE 200 ML','So Bio','Corps','Le Gel Intime Hypoallergénique à la Fleur de Mauve de SO''BiO étic :

Nettoie et apaise les muqueuses sensibles, même les plus réactives, grâce à sa formule innovante sans sulfates.

Est garanti ultra-doux, au pH physiologique et sans parfum.

Assure au quotidien douceur et équilibre de la zone intime, sujette aux sensations d''inconforts (picotement, démangeaisons, irritations, etc.)

Garantit la protection du film hydrolipidique de la peau et des muqueuses des agressions extérieures qui pourraient les irriter.

Application :

Usage externe.

Ne pas avaler (tenir hors de la portée des enfants).

Eviter le contact avec les yeux.

Ne pas jeter dans la nature.',7500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/so-bio-so-bio-gel-intime-haute-tolerance-optimale-200-ml-toilette-intime.jpg?v=1736182881',10,1,'8140383158447','44791210836143','https://beautymarket.ma/products/so-bio-gel-intime-fleur-de-mauve-hypoallergenique-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/so-bio-so-bio-gel-intime-haute-tolerance-optimale-200-ml-toilette-intime.jpg?v=1736182881"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DR ORGANIC DENTIFRICE A L''ALOE VERA 100 ML','Dr Organic','Hygiène','3 actions en 1 dentifrice : il a un effet apaisant, il éclaircit légèrement et il lutte contre les caries au quotidien. L''Aloe Vera, la mousse d''Islande, le marronier d''Inde et l''arbre à thé (tea tree) font de ce produit un soin idéal pour l''hygiène buccale quotidienne. Ce dentifrice apaise et régénère les gencives, et protège également des bactéries, qui sont la principale cause de plaque et du tartre.',7500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dr-organic-dentifrice-a-l-aloe-vera-100-ml.jpg?v=1736183303',10,1,'8140383518895','44791212310703','https://beautymarket.ma/products/dr-organic-dentifrice-a-laloe-vera-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dr-organic-dentifrice-a-l-aloe-vera-100-ml.jpg?v=1736183303"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
