INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET GEL DOUCHE JEAN MARIE FARINA 200 ML','Roger&Gallet','Corps','Ce Gel Douche parfumé à la mousse onctueuse nettoie la peau en douceur sans la dessécher. Enrichi d''Essence naturelle de Romarin aux vertus relaxantes et d''aloe vera, sa base lavante est 100% d''origine végétale pour une application ultra-douce pour la peau et facile à rincer. Sous la douche ou dans le bain, sa mousse fine procure une exquise sensation de fraicheur et laisse votre peau délicieusement parfumée aux notes aromatiques et hespéridées de l''Eau de Cologne Jean Marie Farina.',16900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roger-et-gallet-roger-et-gallet-gel-douche-jean-marie-farina-200-ml-gels-et-huiles-lavants.jpg?v=1736959034',10,1,'8144263774383','44819230621871','https://beautymarket.ma/products/roger-gallet-gel-douche-jean-marie-farina-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roger-et-gallet-roger-et-gallet-gel-douche-jean-marie-farina-200-ml-gels-et-huiles-lavants.jpg?v=1736959034"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Jean-Marie Farina Savon Parfumé - 100 g','Roger&Gallet','Corps','Ce Gel Douche parfumé à la mousse onctueuse nettoie la peau en douceur sans la dessécher. Enrichi d''Essence naturelle de Romarin aux vertus relaxantes et d''aloe vera, sa base lavante est 100% d''origine végétale pour une application ultra-douce pour la peau et facile à rincer. Sous la douche ou dans le bain, sa mousse fine procure une exquise sensation de fraicheur et laisse votre peau délicieusement parfumée aux notes aromatiques et hespéridées de l''Eau de Cologne Jean Marie Farina.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SAVONNN.png?v=1736959660',10,1,'8144269082799','44819239207087','https://beautymarket.ma/products/roger-gallet-jean-marie-farina-savon-parfume-100-g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SAVONNN.png?v=1736959660","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SAVONN2.png?v=1736959660"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PURIADERM PURIACTIV TRIOPLEX SOIN DEPIGMENTANT INTENSIF 30 ML','Puriaderm','Visage','Puriaderm Puriactiv Trioplex Soin Dépigmentant Intensif 30 ml est votre allié pour retrouver un teint uniforme et éclatant. Ce soin hautement concentré agit directement sur les taches pigmentaires pour réduire leur apparence et prévenir leur réapparition. Idéal pour les peaux sujettes aux irrégularités du teint, il cible efficacement les taches brunes causées par le soleil, le vieillissement ou les déséquilibres hormonaux.

Grâce à sa formule innovante enrichie en ingrédients dépigmentants de pointe, Puriaderm Puriactiv Trioplex offre des résultats visibles dès les premières semaines d’utilisation. Il combine des actifs puissants qui unifient le teint, tout en hydratant et en apaisant la peau pour un confort optimal. Sa texture légère et non grasse pénètre rapidement, permettant une application facile et agréable.

Ce soin dépigmentant convient à tous les types de peau et peut être intégré à une routine de soin quotidienne pour un résultat durable et une peau visiblement plus lumineuse.

Conseils d’utilisation :

Appliquez une petite quantité du soin sur une peau propre et sèche, en insistant sur les zones concernées par les taches.

Utilisez-le matin et soir pour des résultats optimaux.

Pour une protection maximale, associez ce soin à une crème solaire SPF 50 en journée.',27900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ArtbEFEFoard1.jpg?v=1736959507',10,1,'8144269770927','44819240321199','https://beautymarket.ma/products/puriaderm-puriactiv-trioplex-soin-depigmentant-intensif-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ArtbEFEFoard1.jpg?v=1736959507"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Fleur de Figuier Lait Corps Bienfaisant - 250 ml','Roger&Gallet','Corps','Le parfum des figues bien mûres, la sieste aux heures chaudes, la fraicheur de l''ombre des feuillages... Le Lait Corps Bienfaisant Fleur de Figuier nous invite à ralentir le rythme, tout simplement. Enrichi d''extrait naturel de figue aux vertus délassantes et de beurre de Karité, il nourrit la peau et offre une hydratation 24h. Sa texture légère pénètre rapidement et laisse votre peau hydratée et délicieusement parfumée aux notes fruitées ensoleillées de Fleur de Figuier.',22000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/figuerrrr.png?v=1736959933',10,1,'8144272490671','44819243565231','https://beautymarket.ma/products/roger-gallet-fleur-de-figuier-lait-corps-bienfaisant-250-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/figuerrrr.png?v=1736959933","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hghghggj.png?v=1736959933"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC MASQUE GOMMANT 75ML','Lierac','Visage','Composée à 98% d''ingrédients d''origine naturelle, Le Masque Gommant élimine les impuretés, lisse le grain de peau et ravive l''éclat du teint. Au coeur de sa formule, le Complexe Prébiotiques Marin préserve et renforce le microbiote cutané. Enrichi en Kaolin, pour purifier la peau.

Sa texture crèmeuse laisse la peau purifiée, lisse, douce et lumineuse.

VEGAN*
Testé sous contrôle dermatologique.
Made in France

*Sans ingrédients d''origine animale

Sa texture mousse généreuse et aérienne offre un véritable moment de plaisir à l''application et laisse la peau nette, douce et apaisée.

VEGAN*
Testé sous contrôle dermatologique.
Made in France

*Sans ingrédients d''origine animale

LE COMPLEXE PRÉBIOTIQUES
Il offre un apport nutritif complet et équilibré, adapté aux besoins de tous les microbiotes. Composé de 3 ingrédients actifs [eau de mer - algues vertes et brunes - sucre], il fournit les nutriments essentiels au maintien d''un microbiote cutané équilibré.

l''Eau Micellaire élimine en douceur le maquillage et les impuretés.

EFFICACITÉ PROUVÉE

Une efficacité ressentie par les femmes !*

100% peau propre et nette
100% peau douce
95% peau confortable

*Test de satisfaction - 21 femmes - % de satisfaction après la 1ère application.

Conseils d’utilisation :

Appliquer sur le visage une à deux fois par semaine en évitant le contour des yeux.

1. En gommage, masser sur visage humide puis rincer.

2. En masque, laisser poser 5 minutes puis rincer.

 INGREDIENTS :

AQUA / WATER / EAU. GLYCERIN. CAPRYLIC/CAPRIC TRIGLYCERIDE. KAOLIN. ARACHIDYL ALCOHOL. PERLITE. BEHENYL ALCOHOL. BAMBUSA ARUNDINACEA STEM EXTRACT. CETEARYL ALCOHOL. CI 77891 / TITANIUM DIOXIDE. AMMONIUM ACRYLOYLDIMETHYLTAURATE/VP COPOLYMER. ARACHIDYL GLUCOSIDE. SODIUM POLYACRYLATE. PARFUM / FRAGRANCE. CHLORPHENESIN. ETHYLHEXYLGLYCERIN. HELIANTHUS ANNUUS (SUNFLOWER) SEED OIL. MARIS AQUA / SEA WATER / EAU DE MER. TOCOPHEROL. CITRIC ACID. PHENETHYL ALCOHOL. LAMINARIA DIGITATA EXTRACT. CHLORELLA VULGARIS EXTRACT. SACCHARIDE ISOMERATE. ALKANNA TINCTORIA ROOT EXTRACT. 4094A.',24000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/lierac-masque-gommant-75ml.jpg?v=1736960079',10,1,'8144274751663','44819248742575','https://beautymarket.ma/products/lierac-masque-gommant-75ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/lierac-masque-gommant-75ml.jpg?v=1736960079"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
