INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Rose Eau Parfumée 100ml','Roger&Gallet','Corps','Calme et volupté, douceur et tendresse… Rose est une caresse apaisante, de ces caresses amoureuses qui restent sur la peau comme une empreinte intimiste. Signée du Maître Parfumeur Angéline Leporini, elle met en majesté la rose Damascena qui déploie là toutes ses pétales, veloutées et fraîches. Enrichie d''huile d''essentielle naturelle de rose aux vertus relaxantes, elle se déploie inlassablement sur la peau comme un baume de douceur. Mêlée à la mandarine d''Italie, elle vibre d''un éclat vibrant et frais.',56000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roseeee.png?v=1736963055',10,1,'8144298442927','44819333382319','https://beautymarket.ma/products/roger-gallet-rose-eau-parfumee-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roseeee.png?v=1736963055","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/roseee2.png?v=1736963055"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Rose Lait Corps 250ml','Roger&Gallet','Corps','Calme et volupté, douceur et tendresse… Le Lait Corps Bienfaisant Rose à la texture onctueuse nous invite à un moment intimiste de douceur. Enrichi d’extrait naturel de rose aux vertus relaxantes et de beurre de Karité, il nourrit la peau et offre une hydratation 24h. Sa texture légère pénètre rapidement et laisse votre peau hydratée et délicieusement parfumée aux notes veloutées et fraîches du parfum Rose.',22000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/rooodr.png?v=1736963174',10,1,'8144299884719','44819337281711','https://beautymarket.ma/products/roger-gallet-rose-lait-corps-250ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/rooodr.png?v=1736963174"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET ROSE SAVON BOITE 3* 100G','Roger&Gallet','Corps','Icone des salles de bain devenus icones de la pop culture, les savons Roger&Gallet parfument depuis 1879. Fabriqués "au chaudron" selon une méthode artisanale qui perdure encore aujourd''hui, ils sont odorants et vous parfument de leur mousse fine jusqu''à leur dernière utilisation. Cette technique de parfumage "à coeur" nécessite 80 heures de fabrication pour chaque pièce. Habillés de leur emblématique "plissé soleil" aux couleurs pop, ils sont beaux, ils sentent bons, et distillent de la bonne humeur.',24900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ROGER-GALLET-ROSE-SAVON-BOITE-3-100G.jpg?v=1736963369',10,1,'8144301293743','44819340460207','https://beautymarket.ma/products/roger-gallet-rose-savon-boite-3-100g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ROGER-GALLET-ROSE-SAVON-BOITE-3-100G.jpg?v=1736963369"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC LIFT INTEGRAL SERUM TENSEUR 30 ML','Lierac','Cheveux','Le Sérum Lift Integral renforce la structure de la peau en agissant sur ses éléments essentiels (collagène, élastine, acide hyaluronique), mais aussi sur les glycoprotéines qui les connectent. Il est enrichi en biopolymères ultra-tenseurs pour un effet gainant immédiat.

La peau retrouve fermeté, élasticité et rebond, pour un effet lift intégral.

La texture lactée du Sérum Tenseur enveloppe la peau pour un véritable fini velours.

Formulée pour convenir à tous les types de peaux, même sensibles.

L''ARN DE ROSE

L''ARN de rose stimule la synthèse naturelle de collagène, et de sa glycoprotéine associée, la fibronectine. Cet ingrédient d''origine 100% naturelle provient de la rose de Grasse, cultivée sans pesticides.

LA TULIPE NOIRE

La Tulipe Noire stimule la synthèse naturelle d''élastine et de sa glycoprotéine associée, la fibrilline. Issu de 7 années de Recherche, et breveté par Lierac, cet extrait de Tulipe Noire est 100% d''origine naturelle et provient de Hollande.

L''ACIDE HYALURONIQUE

L''Acide Hyaluronique d''origine naturelle repulpe intensément la peau.

CONSEILS D''UTILISATION

Appliquer matin et soir sur le visage et le cou avant la crème.

INGREDIENTS

AQUA / WATER / EAU. COCO-CAPRYLATE/CAPRATE. GLYCERIN. BUTYLENE GLYCOL. XYLITYLGLUCOSIDE. CETYL ALCOHOL. GLYCERYL STEARATE. SODIUM STEAROYL GLUTAMATE. XANTHAN GUM. ANHYDROXYLITOL. CAESALPINIA SPINOSA FRUIT EXTRACT. PARFUM / FRAGRANCE. CITRIC ACID. ETHYLHEXYLGLYCERIN. SODIUM BENZOATE. XYLITOL. SODIUM POLYACRYLATE. HYDROLYZED HYALURONIC ACID. SODIUM PHYTATE. KAPPAPHYCUS ALVAREZII EXTRACT. MALTODEXTRIN. TOCOPHEROL. LECITHIN. ADENOSINE. HELIANTHUS ANNUUS (SUNFLOWER) SEED OIL. TULIPA GESNERIANA FLOWER EXTRACT. ROSA CENTIFOLIA FLOWER EXTRACT. 4102A.',65000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LIERACLIFTINTEGRALLESERUMTENSEUR30ML.png?v=1736963069',10,1,'8144302604463','44819342655663','https://beautymarket.ma/products/lierac-lift-integral-serum-tenseur-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LIERACLIFTINTEGRALLESERUMTENSEUR30ML.png?v=1736963069"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET Fleur d''Osmanthus Eau Parfumée Bienfaisante - 100 ml','Roger&Gallet','Corps','Retrouver le gout euphorisant des premiers beaux jours, la douceur d''une brassée de fleurs toute en légèreté. Fleur d''Osmanthus est une surprise de fraicheur et de gaité, signée du Maitre Parfumeur Nathalie Lorson. Prisé pour ses vertus énergisantes, l''absolu naturel d’osmanthus emplit la composition de ses effluves abricotées et fruitées. Une douceur veloutée transportée par la fraicheur ensoleillée de la Mandarine d''Italie, joyeuse et pétillante. En fond, la puissance ambrée du benjoin vient doper le sillage de ses notes suaves.',56000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/GHGHGHG_00088af0-57a7-495f-ac4a-d2b297588dcb.png?v=1736963784',10,1,'8144304275631','44819350356143','https://beautymarket.ma/products/roger-gallet-fleur-dosmanthus-eau-parfumee-bienfaisante-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/GHGHGHG_00088af0-57a7-495f-ac4a-d2b297588dcb.png?v=1736963784","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/JHJHJHJHJHKLK.png?v=1736963784"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ROGER & GALLET  Fleur d''Osmanthus Savon Bienfaisant - 100 g','Roger&Gallet','Autres soins','Icones des salles de bain devenus icones de la pop culture, les savons Roger&Gallet parfument depuis 1879. Fabriqués "au chaudron" selon une méthode artisanale qui perdure encore aujourd''hui, ils sont odorants et vous parfument de leur mousse fine jusqu''à leur dernière utilisation. Cette technique de parfumage "à coeur" nécessite 80 heures de fabrication pour chaque pièce. Habillés de leur emblématique "plissé soleil" aux couleurs pop, ils sont beaux, ils sentent bons, et distillent de la bonne humeur.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/WDSRTSRTR.png?v=1736964032',10,1,'8144306962607','44819381256367','https://beautymarket.ma/products/roger-gallet-fleur-dosmanthus-savon-bienfaisant-100-g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/WDSRTSRTR.png?v=1736964032","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DXXTDRTRET.png?v=1736964032"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC LIFT INTEGRAL Crème Cou & Décolleté 50 ML','Lierac','Visage','Pour qui : Tous les types de peaux.

Résultats beauté : Une peau plus ferme et lissée.

Actifs : ARN Rose, Tulipe Noire, Acide Hyaluronique.

On aime : Sa texture gel-crème à pénétration rapide



La Crème Cou & Décolleté Lift Integral de Lierac est un soin ciblé fermeté à effet lissant immédiat conçu pour tous types de peaux, même les plus sensibles.

Elle renforce la structure de la peau en agissant sur ses éléments essentiels (collagène, élastine, acide hyaluronique), mais aussi sur les glycoprotéines qui les connectent.

Elle est enrichie en biopolymères ultra-tenseurs pour un effet lissant immédiat.

La peau retrouve fermeté, élasticité et rebond, pour un effet lift intégral.

Le décolleté est visiblement défroissé et le cou est regalbé.

Sa texture gel-crème à pénétration rapide hydrate intensément, tout en apportant confort et fraicheur à la peau.

Sa formule est composée à 97% d''ingrédients d''origine naturelle.

Fabriqué en France.',68000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/P0752028_P.jpg?v=1736964013',10,1,'8144308240559','44819393970351','https://beautymarket.ma/products/lierac-lift-integral-creme-cou-decollete-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/P0752028_P.jpg?v=1736964013"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC ARKESKIN LA CREME JOUR MENOPAUSE 50ML','Lierac','Solaires','Lierac Arkéskin La Crème Jour Ménopause corrige les signes visibles de la ménopause sur la peau : sécheresse

Formulée à 97% d’ingrédients d’origine naturelle, La Crème Jour Ménopause corrige les signes visibles de la ménopause sur la peau : sécheresse, perte de densité et de fermeté. Inspirée des rythmes biologiques de la peau, La Crème Jour renforce la protection cutanée et nourrit durablement la peau. Spécifiquement développée pour les femmes qui traversent la ménopause, sa texture fond délicatement sur la peau pour lui apporter un confort immédiat. Jour après jour la peau retrouve densité, fermeté et confort.

100% d’origine naturelle, L’Acide Hyaluronique de haut poids moléculaire maintient l’équilibre hydrique de la peau grâce à son fort pouvoir hygroscopique, pour une action immédiate sur l’hydratation. La peau est intensément hydratée, repulpée et plus confortable.

Conseils d''application

Appliquer le matin sur le visage et le cou. Pour une meilleure efficacité, utiliser en complément La Crème Nuit Ménopause.',45000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/68bba905830f4fe02be3b2fb3ea9fe7b.jpg?v=1736964694',10,1,'8144315023535','44819422576815','https://beautymarket.ma/products/lierac-arkeskin-la-creme-jour-menopause-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/68bba905830f4fe02be3b2fb3ea9fe7b.jpg?v=1736964694"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC ARKESKIN LA CREME NUIT MENOPAUSE 50ML','Lierac','Visage','Lierac Arkéskin La Crème Nuit Ménopause active la régénération cellulaire et nourrit durablement la peau.

Formulée à 96% d’ingrédients d’origine naturelle, La Crème Nuit Ménopause corrige les signes visibles de la ménopause sur la peau : sécheresse, perte de densité et de fermeté. Inspirée des rythmes biologiques de la peau, La Crème Nuit active la régénération cellulaire et nourrit durablement la peau. Spécifiquement développée pour les femmes qui traversent la ménopause, sa texture onctueuse fond délicatement sur la peau pour lui apporter un confort immédiat. Jour après jour la peau retrouve densité, nutrition, fermeté et confort.

100% d’origine naturelle, L’Acide Hyaluronique de haut poids moléculaire maintient l’équilibre hydrique de la peau grâce à son fort pouvoir hygroscopique, pour une action immédiate sur l’hydratation. La peau est intensément hydratée, repulpée et plus confortable.',45000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/lierac-arkeskin-menopause-night-cream-50ml-1.png?v=1736965129',10,1,'8144319676591','44819448135855','https://beautymarket.ma/products/lierac-arkeskin-la-creme-nuit-menopause-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/lierac-arkeskin-menopause-night-cream-50ml-1.png?v=1736965129"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
