INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LIERAC HOMME GEL DOUCHE INTÉGRAL 200ML','Lierac','Cheveux','Lierac Homme Gel Douche Intégral douce et soyeuse, la peau est nette, hydratée et stimulée.

Gel douche intégral : le tout-en-un
