INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MAYBELLINE NEW YORK SKY HIGH Waterproof MASCARA','Maybelline','Maquillage','Des cils d’une longueur vertigineuse avec Cils Sensational Sky High, mascara volume et longueur illimitée.

Des cils d’une longueur vertigineuse avec Cils Sensational Sky High, mascara volume et longueur illimitée. Sa brosse flexible capture tous les cils, même les plus petits, pour les allonger et les étirer de la racine jusqu’à la pointe. Sa formule, enrichie en extraits de bambou et de fibres, délivre un volume intense et une longueur illimitée, sans alourdir les cils.Sa brosse flexible capture tous les cils, même les plus petits, pour les allonger et les étirer de la racine jusqu’à la pointe. Sa formule, enrichie en extraits de bambou et de fibres, délivre un volume intense et une longueur illimitée, sans alourdir les cils. Volume et longueur illimitée sans paquet.

Testé sous contrôle ophtalmologique. Convient aux yeux sensibles et porteurs de lentilles.

Conseils d''utilisation:

Positionnez la brosse horizontalement et appliquez le mascara de la racine à la pointe en étirant les cils au maximum. Renouvelez l’opération pour obtenir l’effet désiré.Se démaquille facilement.',12500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/skywtp.png?v=1737114527',10,1,'8145783324847','44826668761263','https://beautymarket.ma/products/maybelline-new-york-sky-high-waterproof-mascara',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/skywtp.png?v=1737114527","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/30167223-11.png?v=1737114527","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/skyyyj.png?v=1737114527","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/sku5.png?v=1737114527","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/skuuuu.png?v=1737114527","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/30167223_1.jpg?v=1737113943","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Photo4-DAS24-12088186_SkyHigh_2024_Waterproof_EM_Ehlana_Spd.jpg?v=1738678673"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maybelline Express Brow Ultra Slim Pencil Eyebrow Makeup SOFT BROWN 02','Maybelline','Maquillage','Crayon à sourcils ultra fin Express Brow. La formule douce glisse sur les sourcils sans laisser de traces de couleur et sans casser le crayon pour des sourcils définis avec précision et qui durent !

Bénéfits:

Prenez l''express pour des sourcils parfaitement dessinés. Découvrez le crayon à sourcils Express Brow Ultra Slim de Maybelline New York. C''est le moyen infaillible de rehausser et de définir vos sourcils. Dites adieu aux sourcils clairsemés et bonjour aux sourcils fournis et naturels. Grâce à sa formule résistante à la casse et à sa brosse à spirale intégrée, ce crayon à sourcils ultra fin crée des sourcils parfaitement définis, sans sauter ni tirer. Obtenez votre billet pour une application sans effort et une précision express. Disponible en sept teintes de sourcils. Testé sous contrôle ophtalmologique. Convient aux porteurs de lentilles de contact.',9000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SOFTTT02.png?v=1739619594',10,1,'8145789386927','44826689274031','https://beautymarket.ma/products/maybelline-express-brow-ultra-slim-pencil-eyebrow-makeup-soft-brown',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SOFTTT02.png?v=1739619594","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SOFTT.png?v=1739619594"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
