INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ADERMA CYTELIUM IRRITATIONS CUTANEES SPRAY ASSECHANT 100 ML','A-Derma','Visage','Ce spray a la texture aqueuse et légère, composée de seulement sept ingrédients à 99 % d''origine naturelle. Il assèche et apaise sans colorer la peau, les plis, les zones intimes externes, l''épiderme fessier et les zones fragilisées sujettes à macération, dès la première application. Une formule sans parfum, d''origine naturelle et haute tolérance adaptée à toute la famille.

Les bienfaits :

• ASSÈCHE les peaux irritées sujettes à macération - Spray asséchant.
• APAISE immédiatement les zones irritées sujettes à macération.
• RESPECTE la peau grâce à sa formule minimaliste, naturelle et haute tolérance.

Conseils d''utilisation:

Nettoyer et assainir la zone irritée avant application. Agiter le flacon.
Appliquer 2 à 3 fois par jour.
Ne pas vaporiser vers les yeux.',11700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/a-derma-aderma-cytelium-irritations-cutanees-spray-assechant-100-ml-home.jpg?v=1738773112',10,1,'8158332518575','44883308445871','https://beautymarket.ma/products/aderma-cytelium-irritations-cutanees-spray-assechant-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/a-derma-aderma-cytelium-irritations-cutanees-spray-assechant-100-ml-home.jpg?v=1738773112"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
