INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PRESIDENT DENTURE CRÈME ADHÉSIVE 20G','President','Hygiène','Avec sa combinaison spéciale de principes actifs ultra purs, cette crème est un cadre rapide assurant que vos prothèses dentaires restent en place toute la journée. Son complexe soigneusement équilibré de co-polymères, de gomme et de résines scelle toutes les lacunes vides entre vos gencives et les prothèses dentaires parfaitement, empêchant ainsi le risque d’attraper des aliments entre ceux-ci et donc menant à la mauvaise haleine. La dernière étape de la production de cet adhésif implique un procédé délicat et soigneusement calibré de déshydratation sous vide forcé pour une plus longue durée de conservation, ce qui signifie que ce produit est exempt de conservateurs et d’agents antimicrobiens. Une fois appliquée à votre palais et aux gencives, cette pâte adhésive aide à prévenir et ralentir la fermentation irritante, ainsi que l’inflammation aux points de pression et micro plaies ennuyeuses causées par aphthae plaies.',3000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8030009700214.jpg?v=1738836812',10,1,'8158753292463','44885165146287','https://beautymarket.ma/products/president-denture-creme-adhesive-20g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8030009700214.jpg?v=1738836812"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
