INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('President Brosse A Dent Active soft','President','Hygiène','Avec sa conception avancée et ses caractéristiques innovantes, cette brosse à dents offre une performance optimale.

