INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('President Brosse A Dent Sensitive Extra-Soft','President','Hygiène','La PRESIDENT Brosse à Dents Sensitive Extra-Soft vous offre une expérience de brossage tout en douceur et en efficacité. Dotée d’une tête compacte et d’un manche ergonomique, elle est conçue pour un nettoyage interdentaire minutieux et un massage délicat du bord gingival. De plus, ses poils microfins et internes en microfibre permettent d’éliminer la plaque bactérienne tout en préservant l’émail dentaire.',3800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/juyhj.jpg?v=1738844397',10,1,'8158793367727','44885294710959','https://beautymarket.ma/products/president-brosse-a-dent-sensitive-extra-soft',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/juyhj.jpg?v=1738844397"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
