INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('president Bain bouche active 200ml','President','Hygiène','Vos gencives reculent, vous pouvez avoir des poches irritées et érythémateux, et courir le risque de développer une instabilité dans vos dents qui peuvent tomber.

Cette action antibactérienne et astringente de ce rince-bouche garantit le contrôle et l’amélioration générale de l’irritation des gencives et d’autres problèmes.

Un mélange équilibré de triclosan, de fluorure de sodium, de citrate de zinc et de Sanguinaria canadensis et d’Hawthorn s’oppose à la plaque, réduit la prolifération des bactéries, évite la carie dentaire et resserre les gencives, avec un bon traitement de la maladie parodontale.',5500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bain-bouche-active-250ml.jpg?v=1738845659',10,1,'8158800969903','44885311291567','https://beautymarket.ma/products/president-bain-bouche-active-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/bain-bouche-active-250ml.jpg?v=1738845659"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
