INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PRESIDENT DENTIFRICE ORTHO-IMPLANT 75ML','President','Hygiène','Composition : Calcium, Papaïne, Chlorure de Cetylpyridinium.

