INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('FILORGA SKIN-PREP GEL NETTOYANT AUX AHA 150ML','Filorga','Visage','Le gel nettoyant micro-peeling aux AHA visant à débarrasser la peau des impuretés, à la clarifier et à réduire sa brillance. Il possède également une action lissante et un effet anti-pollution.

