INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ecrinal Shampooing Cheveux Gras 200ml','Ecrinal','Cheveux','Le cheveu sec se caractérise par une apparence terne. Il est rêche au toucher et fréquemment fragile donc cassant.

