INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('GUM BROSSE A DENTS Ortho Travel soft 125','Gum','Hygiène','La brosse à dents Butler Gum Ortho Travel est pratique à transporter. Elle est egalement efficace pour le brossage des dents des personnes porteuses d''un appareil orthodontique.

La brosse à dents orthodontique Travel de Gum se replie dans son manche qui fait office d''étui de transport. Celui-ci est percé, permettant ainsi l''aération de la brosse, pour une meilleure hygiène. Une fois repliée dans son étui, la brosse à dents Ortho Travel de Gum se glissera facilement dans un sac ou même une poche. Une fois rentrés dans la coque créée par le manche, les brins seront protégés des éventuelles poussières et impuretés. Elle permettra d''éviter d''avoir à emporter un volumineux étui pour brosse à dents classique. Pour garder la brosse saine entre deux utilisations, ses brins sont imprégnés de chlorhexidine, un antiseptique à large spectre qui va empêcher les bactéries de proliférer.',3700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gum-szczoteczka-ortodontyczna_13053.jpg?v=1770123805',10,1,'8164159389871','44906937122991','https://beautymarket.ma/products/gum-brosse-a-dents-orthodontie-ambulatoire-125',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/gum-szczoteczka-ortodontyczna_13053.jpg?v=1770123805"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
