INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Erayba ABH Volume Shampooing 250ml','Erayba','Cheveux','Volume amplifié : Renforce et épaissit les cheveux pour un effet volumineux et naturel.

