INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DODIE BIBERON ANTI COLIQUE TETINE RONDE 3 VITESSES + 330ML BLEU POMPIER +6 M','Dodie','Bébé & Maman','Description:

Biberon Initiation+ 330mL, décors Mickey Bleu, équipé d’une tétine ronde 3 vitesses débit rapide Son système anti-colique est intégré à la tétine grâce à une valve brevetée, qui favorise la circulation de l''air et réduit les risques de coliques, d''aérophagie et de régurgitations  La tétine ronde 3 vitesse permet d''adapter le débit au rythme de succion de bébé, en alignant le repère avec le nez de bébé au cours du repas, et elle est adoptée par 9 bébés sur 10 (test réalisé par l’IDM en mars 2013 auprès de 60 mamans d’enfants âgés de 7 à 12 mois) Ce biberon triangulaire est, facile à prendre en main et garanti sans bisphénol A ni S (conformément à la réglementation en vigueur)',12200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-dodie-biberon-anti-colique-tetine-ronde-3-vitesses-330ml-bleu-pompier-6-m-biberons-et-goupillons.jpg?v=1739351336',10,1,'8166219382959','44913039868079','https://beautymarket.ma/products/dodie-biberon-anti-colique-tetine-ronde-3-vitesses-330ml-bleu-pompier-6-m',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dodie-dodie-biberon-anti-colique-tetine-ronde-3-vitesses-330ml-bleu-pompier-6-m-biberons-et-goupillons.jpg?v=1739351336"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
