INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('L’oréal paris sérum visage anti-rides hyaluron expert repulpant 1,5% d''acide hyaluronique','L''Oréal Paris','Maquillage','Hyaluron Expert Sérum repulpant Anti-rides de L’Oréal Paris formulé à base de 1,5% d’Acide Hyaluronique. La peau est visiblement repulpée en une semaine. Sérum Il hydrate et lisse instantanément la peau, son absorption est rapide et sa finition non grasse permet un maquillage parfait !
