INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Neutrogena lipcare Stick Lèvre SPF4 Formul','Neutrogena','Autres soins','Bienfaits:

