INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('COSRX TONER AHA / BHA CLARIFYING TREATMENT 280 ML','Cosrx','Visage','La COSRX AHA/BHA Clarifying Treatment Toner :est un tonique exfoliant doux qui peut aider à améliorer la texture et le teint de la peau

