INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('THE ORDINARY PACK THE DAILY SET','The Ordinary','Visage','Craquez pour cette routine de soins The Ordinary!
