INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ABSOLUTE NEW YORK Nude Essentials Makeup Brush Se','Absolute New York','Cheveux','Set de 6 Pinceaux de Maquillage – Tout ce qu’il vous faut pour définir, estomper et sublimer votre look glam.

