INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MDC MAGICIAN SÉRUM ANTI-ACNÉ 30ML','MDC','Visage','Notre Crème Anti-acné Magician est spécialement conçue pour offrir une solution efficace aux peaux sujettes à l’acné. Enrichie d’ingrédients hydratants et d’agents exfoliants doux, elle procure une peau plus douce et mieux hydratée. Sa formule cible les imperfections tout en apaisant la peau, réduisant ainsi les rougeurs et l’inflammation. Profitez d’une peau plus lisse, plus claire et plus éclatante avec notre Crème Anti-acné Magician.',30500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MDC-Magicien-Serum-Anti-Acne-30ml_1.jpg?v=1741262554',10,1,'8179475677359','44964395581615','https://beautymarket.ma/products/mdc-excellence-72h-creme-hydratante-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MDC-Magicien-Serum-Anti-Acne-30ml_1.jpg?v=1741262554"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
