INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('elmex Dentifrice anti-caries enfant 3-6 ans 50ml','Elmex','Bébé & Maman','Les dents de lait méritent la meilleure protection et le plus grand soin car elles réservent l’espace aux dents définitives et conditionnent leur bonne santé.
