INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Soulsisters Sérum Anti-imperfection 30ML','SoulSisters','Visage','Un sérum de nuit anti imperfections puissant enrichi par 1,5 % d''acide salicylique, 2.9% d’acide glycolique et de prébiotiques pour décongestionner la peau tout en ciblant les éruptions cutanées, l''excès de sébum, les points noirs et les imperfections.

