INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Eclin Baume a Levres 15ml','Eclin','Solaires','Le Baume à Lèvres Eclin offre une hydratation intense et une protection efficace pour des lèvres douces et souples toute la journée. Sa formule riche en ingrédients nourrissants et apaisants aide à réparer les lèvres sèches et gercées, les laissant visiblement plus douces et plus lisses.

