INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('YEOUTH Retinol Eye Cream','Yeouth','Visage','La crème YEOUTH Retinol hydratante pour les yeux est conçue pour hydrater la peau délicate autour des yeux, améliorant ainsi l''apparence des ridules. Le rétinol est un type spécifique de rétinol pour le visage. Cette crème éclaircissante pour les cernes et les poches est formulée avec du rétinol à libération prolongée encapsulé pour améliorer l''apparence de la peau délicate autour des yeux. L''acide hyaluronique apporte de l''hydratation et éclaircit la peau, tandis que le complexe tripeptide aide à donner un aspect plus ferme aux yeux fatigués et réduit l''apparence des poches. Vous remarquerez une amélioration visible de l''apparence autour de vos yeux. Dites bonjour à une zone oculaire plus',26500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ASW200014470_101.webp?v=1743787692',10,1,'8199369162927','45040931733679','https://beautymarket.ma/products/yeouth-retinol-eye-cream',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ASW200014470_101.webp?v=1743787692"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
