INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('YEOUTH Hyaluronic Acid Plus 30 ML','Yeouth','Visage','Ravivez votre jeunesse avec le sérum acide hyaluronique YEOUTH enrichi en vitamine C. Conçu pour illuminer et améliorer l''apparence de votre peau, il resserre et ravive le teint grâce à son mélange d''acide hyaluronique, vitamine C et tripeptide-31. Convient à tous types de peau, même les plus sensibles, et peut être combiné avec d''autres sérums pour une peau énergisée et éclatante.',26500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus.webp?v=1743788418',10,1,'8199374241967','45040942153903','https://beautymarket.ma/products/yeouth-hyaluronic-acid-plus-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus.webp?v=1743788418","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus_ART.webp?v=1743788418","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus_2.webp?v=1743788418","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus_4.webp?v=1743788418","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/YEOUTH_Hyaluronic_Acid_Plus_3.webp?v=1743788418"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('YEOUTH Vitamin C & E Serum 30 ML','Yeouth','Cheveux','Ravivez votre jeunesse avec le sérum acide hyaluronique YEOUTH enrichi en vitamine C. Conçu pour illuminer et améliorer l''apparence de votre peau, il resserre et ravive le teint grâce à son mélange d''acide hyaluronique, vitamine C et tripeptide-31. Convient à tous types de peau, même les plus sensibles, et peut être combiné avec d''autres sérums pour une peau énergisée et éclatante.',24500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7b286754e6956c413294209265f134c7.jpg?v=1743789495',10,1,'8199374995631','45040943431855','https://beautymarket.ma/products/yeouth-vitamin-c-e-serum-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7b286754e6956c413294209265f134c7.jpg?v=1743789495"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MEDICUBE PDRN PINK HYALURONIC MOISTURIZING CREAM 50 ML','Medicube','Visage','Offrez à votre peau une cure de jouvence complète avec la crème hydratante hyaluronique rose MEDICUBE PDRN. Sa formule innovante, enrichie en PDRN de saumon, en niacinamide et en 10 couches d''acide hyaluronique, cible les imperfections tenaces, unifie le teint et renforce la barrière cutanée. Cette crème hydratante polyvalente hydrate intensément votre peau, lui apportant éclat et souplesse. Le PDRN de saumon et la niacinamide agissent en synergie pour éclaircir la peau et réduire les imperfections, tandis que les 10 couches d''acide hyaluronique hydratent en profondeur, laissant votre peau douce et rebondie. Sa texture légère et non grasse est idéale pour une utilisation quotidienne, s''adaptant à tous les types de peau. Offrez à votre peau le soin qu''elle mérite avec la crème hydratante hyaluronique rose MEDICUBE PDRN.

Une crème hydratante polyvalente pour une peau éclatante et sans imperfections

La crème hydratante hyaluronique rose MEDICUBE PDRN 50 ML est un véritable concentré de bienfaits pour votre peau :

PDRN de saumon et niacinamide : Éclaircissent la peau et réduisent les imperfections.

10 couches d''acide hyaluronique : Hydratent intensément et en profondeur.

Réduit les imperfections et unifie le teint : Pour une peau plus lisse et uniforme.

Renforce la barrière cutanée : Pour une peau plus résistante aux agressions extérieures.

Texture légère et non grasse : Idéale pour une utilisation quotidienne.

Apporte éclat et souplesse : Pour une peau visiblement plus saine.

Marque de confiance : MEDICUBE est reconnue pour ses produits de soin innovants et efficaces.

Conseils d''utilisation :

Appliquez une noisette de crème sur une peau propre et sèche, matin et soir.

Massez délicatement jusqu''à absorption complète.

Insistez sur les zones sujettes aux imperfections ou à la sécheresse.

Peut être utilisée seule ou après votre sérum habituel.',27500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XXL_p0214014536_600x_9cffb341-d13a-4ee0-9cee-9fe693b70065.webp?v=1743849071',10,1,'8199532052655','45042070257839','https://beautymarket.ma/products/medicube-pdrn-pink-hyaluronic-moisturizing-cream-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/XXL_p0214014536_600x_9cffb341-d13a-4ee0-9cee-9fe693b70065.webp?v=1743849071"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL PROFASHION CREAM BLUSH DAZZLING N 41','Pastel','Maquillage','Découvrez le Blush Crème Pastel Profashion 41, un blush crème polyvalent conçu pour un fini naturel et frais. Sa formule onctueuse glisse en douceur pour un teint frais et éclatant.
Code produit : 1079BZRC4374

