INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MACADAMIA NOURISHING REJUVENATING SHAMPOO 1 LTR','Macadamia','Cheveux','Le shampooing régénérateur Macadamia est conçu pour hydrater et protéger tous les types de cheveux et particulièrement recommandé pour les cheveux secs et endommagés.

Il nettoie avec délicatesse les cheveux traités chimiquement et abimés. Il permet de les hydrater sans laisser de dépôts alourdissants et protège contre les agressions quotidiennes de l''environnement.

Sa composition sans SULFATE et PARABEN permet de l''utiliser en entretien du lissage brésilien. Toute la gamme est fabriquée a Los Angeles, USA. Elle n''est pas testée sur les animaux.',45600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7702114.webp?v=1744627543',10,1,'8203135811759','45062058311855','https://beautymarket.ma/products/macadamia-nourishing-rejuvenating-shampoo-1-ltr',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/7702114.webp?v=1744627543"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MACADAMIA PRO DEMELANT HYDRATANT LEGER WEIGHTLESS CONDITIONER 500ML','Macadamia','Cheveux','Cet après-shampoing réparateur léger démêle, renforce et apporte volume et volume aux cheveux.

• Contient le complexe exclusif Pro Oil, un mélange d''huiles thérapeutiques de macadamia et d''argan qui favorise la santé et la force des cheveux.

