INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL PROFASHION EYESHADOW PALETTE So In Love 201','Pastel','Maquillage','Profashion So In Love Eyeshadow Palette – Bella

