INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ANIVAGENE SERUM CILS ET SOURCILS 10 ML','Anivagene','Cheveux','Anivagène Sérum Cils et Sourcils 10 ml

