INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MANIX SKYN INTENSE FEEL BOÎTE 3','Manix','Visage','SKYN, la matière Presque imperceptible. Intense Feel est le le 1er préservatif stimulant sans latex. La matière révolutionnaire des préservatifs SKYN® restitue des sensations plus naturelles, plus douces et plus intenses.

