INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('I M FROM YEOJU KOREA RICE TONER 150 ML','I''m From','Visage','La lotion tonique au riz I’M FROM est une lotion éclaircissante et hydratante qui cible les peaux ternes, irritées ou vieillissantes. Formulé à partir de riz Yeoju moulu et de 77,78 % d’extrait de Goami, ce tonique exfolie les impuretés pour une peau plus lisse et plus hydratée.

