INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HEI POA SOIN CAPILLAIRE-PUR MONOI DE TAHITI CHEVEUX SECS ET ABIMES 100','Hei Poa','Solaires','Grâce à l’effet nourrissant et réparateur du monoï, ce soin capillaire pur monoï Hei Poa est idéal pour les cheveux secs, abimés ou cassants. L’association du monoï et d’un hydratant capillaire aide à protéger les cheveux du dessèchement, leur apporte brillance et facilite leur coiffage.

