INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HEI POA SHAMPOOING DOUCHE A LA PULPE DE COCO BIO 150ML','Hei Poa','Cheveux','L''odeur gourmande de la Noix de Coco : un parfum enivrant et sensuel qui se rapproche du goût sucré de l''amande rapée de noix de coco, celui de nos gâteaux, ou encore d''un cocktail blanc avec une paille par 30° à l''ombre. Ce parfum de Pulpe de Coco réveille la chaleur de la peau, la sensualité des touchés humides, et donne un sens à l''exotisme, pour ne pas dire érotisme.',5400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hei-poa-shampooing-douche-a-la-pulpe-de-coco-bio-150ml.jpg?v=1747829128',10,1,'8221648158895','45173542420655','https://beautymarket.ma/products/hei-poa-shampooing-douche-a-la-pulpe-de-coco-bio-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/hei-poa-shampooing-douche-a-la-pulpe-de-coco-bio-150ml.jpg?v=1747829128"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
