INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VITABIO COOL FRUITS POMME PECHE ABRICOT 4 X 90G','Vitabio','Bébé & Maman','Vitabio Cool Fruits Pomme Peche Abricot 4x90g, convient à partir de 8 mois.

