INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NIVEA SUN UV FACE SENSITIVE SPF50 CRÈME SOLAIRE 50ML','Nivea','Solaires','Cette crème solaire hautement efficace avec la protection ultra spectre protège la peau des dommages cutanés causés par les UVA & UVB et des effets de la Lumière Visible de Haute Énergie (LVHE), tels que le vieillissement prématuré de la peau.

