INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NIVEA MEN Déodorant Spray Dry Impact 72h 200ml – Protection Anti-Transpirante Longue Durée','Nivea','Visage','NIVEA MEN Déodorant Spray Dry Impact 72h 200ml


