INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MAVIDERMA GEL NETTOYANT SURGRAS 500ML','Maviderma','Visage','MAVIDERMA gel nettoyant surgras à la texture douce et onctueuse nettoie efficacement et avec douceur les peaux fragiles, sa texture confortable rend son utilisation quotidienne agréable.

