INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MAVIDERMA GEL NETTOYANT PURIFIANT 500 ML','Maviderma','Autres soins','MAVIDERMA Gel Nettoyant Purifiant – 500 ml

Purifying Cleansing Gel – Sebum Regulating · Cleanses · Purifies

