INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BETADENT DENTIFRICE TOTAL TRIPLE ACTION 100 ML','Betadent','Hygiène','Dentifrice à action totale contre les principaux problèmes d''hygiène bucco-dentaire : plaque, tartre, caries, gencives délicates et mauvaise haleine.

