INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION BRONZER RELOADED LONG WEEKEND','Revolution','Autres soins','Avec notre poudre bronzante Baked, une seule application suffit pour une allure "retour de plage". Nouveauté de notre gamme de produits Re-loaded la plus vendue, cette poudre nacrée apporte aux teints clairs un éclat ensoleillé. De plus, il s''agit d''une palette compacte qui permet de créer aisément une couleur naturelle lors de vos déplacements. Balayez les zones du visage à réchauffer ou procédez à une application humide sur vos paupières pour un regard intense. Poursuivez avec le Revolution Highlight Re-loaded pour une éclat hyper rayonnant. Sans cruauté.',5500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBronzerReloadedLongWeekend1_5f19638c-7f93-4e33-9488-dd195eb5e282.jpg?v=1753902783',10,1,'8279628808367','45741341474991','https://beautymarket.ma/products/revolution-bronzer-reloaded-long-weekend',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBronzerReloadedLongWeekend1_5f19638c-7f93-4e33-9488-dd195eb5e282.jpg?v=1753902783"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION BROW FIXER','Revolution','Autres soins','Ce gel à sourcils doux et nourrissant vous aide à garder vos sourcils en place, tout en créant un arc parfait. L''applicateur précis vous permet d''apprivoiser n''importe quels sourcils, des plus fournis aux plus fins.',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBrowFixer1_bd808925-c99f-4193-bb76-71ce2ceab994.jpg?v=1753902784',10,1,'8279628841135','45741341507759','https://beautymarket.ma/products/revolution-brow-fixer',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBrowFixer1_bd808925-c99f-4193-bb76-71ce2ceab994.jpg?v=1753902784"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION BROW POMADE DARK BROWN','Revolution','Autres soins','Parfaitement sans bavures, Makeup Revolution Brow Pomade est parfaite pour des sourcils impeccables et durables. Dotée d''une brosse à sourcils permettant d''appliquer facilement la crème, la pommade vous donne des sourcils bien définis grâce à un fini imperméable et sans bavures.',12500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FEZFZ.jpg?v=1775502589',10,1,'8279628906671','45741343277231','https://beautymarket.ma/products/revolution-brow-pomade-dark-brown',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FEZFZ.jpg?v=1775502589","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/REV_9d225219-5a54-442f-aa51-42f2823ef781.jpg?v=1775502589","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DERE.jpg?v=1775502812"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION BROW POMADE MEDIUM BROWN','Revolution','Autres soins','Parfaitement sans bavures, Makeup Revolution Brow Pomade est parfaite pour des sourcils impeccables et durables. Dotée d''une brosse à sourcils permettant d''appliquer facilement la crème, la pommade vous donne des sourcils bien définis grâce à un fini imperméable et sans bavures.',12500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BROWPOMADEMEDIUMBROWN2_37c4d0c7-7f8c-4f74-bcae-f624895f04cc.jpg?v=1753902789',10,1,'8279628972207','45741343309999','https://beautymarket.ma/products/revolution-brow-pomade-medium-brown',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/BROWPOMADEMEDIUMBROWN2_37c4d0c7-7f8c-4f74-bcae-f624895f04cc.jpg?v=1753902789"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION BROW SCULPT KIT MEDIUM','Revolution','Autres soins','Voici notre mini héros des sourcils, tout ce dont vous avez besoin en un seul kit pour sculpter vos sourcils en déplacement (ou à la maison). Brow Sculpt Kit est une  palette de sourcils 3 en 1 comprend un gel pour sourcils, une poudre, un surligneur, une pince à épiler, une brosse et un embout pour un résultat optimal et des sourcils éclatants. Ce kit multitâche vous permet de réaliser une multitude de looks de sourcils, des plus audacieux aux plus naturels.',7900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBrowSculptKitMedium1_8a20e097-6436-4b4d-aee7-4fba66ebcd06.jpg?v=1753902791',10,1,'8279629004975','45741343473839','https://beautymarket.ma/products/revolution-brow-sculpt-kit-medium',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionBrowSculptKitMedium1_8a20e097-6436-4b4d-aee7-4fba66ebcd06.jpg?v=1753902791"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION CHEEK KIT DON''T HOLD BACK','Revolution','Autres soins','Appliquez bronzant et enlumineur en une seule fois. Les pouvoirs de la poudre bronzante et d''un highlighter unissent leurs forces dans une palette compacte à quatre teintes. Multidimensionnel ! Chaque teinte brillante hautement pigmentée a une texture soyeuse qui glisse parfaitement sur la peau et un effet marbré bicolore conçu pour ajouter une radiance multidimensionnelle. Et le meilleur ? Il s''agit du meilleur produit multi-tâches, idéal pour minimiser le maquillage à emporter dans votre sac. Utilisez-le individuellement pour définir, dessiner les contours et mettre en évidence les pommettes et les tempes, ou faites tourner votre brosse autour de l''ensemble de la zone compacte pour une lumière naturelle. Nous l''aimons également pour les yeux : appliquez-le sur peau humide pour créer une finition intense étincelante.',7300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionCheekKitDon_tHoldBack1_236f14e5-8352-44da-82f6-13a5dbfa417c.jpg?v=1753902793',10,1,'8279629037743','45741343506607','https://beautymarket.ma/products/revolution-cheek-kit-dont-hold-back',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/RevolutionCheekKitDon_tHoldBack1_236f14e5-8352-44da-82f6-13a5dbfa417c.jpg?v=1753902793"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION CONCEAL & DEFINE C11','Revolution','Autres soins','Le produit qui a brisé Internet lors de son lancement en 2018 - continue d''être l''étalon-or des correcteurs, quel que soit votre budget. Récipiendaire de plusieurs prix. Sans cruauté, végétalien ET best-seller. Un correcteur Conceal & Define se vend toutes les 20 secondes au Royaume-Uni. Pourquoi? Ce correcteur au fini mat, léger mais complet, couvre les imperfections, uniformise le teint et neutralise les cernes. Son pigment intense, résistant aux plis et longue tenue, dure 16 heures et peut être utilisé pour donner du contour et ajouter de la définition. L''applicateur de pied de biche permet l''application la plus douce qui ne traîne pas sur la peau délicate sous vos yeux. De plus, il est désormais non comédogène, ce qui signifie qu’il ne bloque pas vos pores et ne provoque pas d’éruptions cutanées. Nous croyons tellement en son éclat que nous avons demandé à 50 fans de Revolution du monde entier de participer à notre campagne Zero Retouch.

