INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION FAST BASE CONTOUR STICK DARK','Revolution','Autres soins','le stick double-embout spécialement conçu pour sublimer les tons de peau plus foncés. Notre formule innovante et légère se fond harmonieusement dans votre peau, offrant un contouring sans pareil, sans aucune démarcation disgracieuse. Mettez en valeur et sculptez votre visage avec aisance grâce à notre produit qui saura attirer tous les amateurs de contouring et de nuances sombres. Obtenez un look saisissant qui fera tourner les têtes et révélera toute votre beauté avec notre solution de contouring spécialement adaptée à votre teint.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MakeupRevolutionFastBaseContourStickDark1_a4008efb-caa2-40a1-bcab-3ef41a955518.jpg?v=1753902837',10,1,'8279630086319','45741348683951','https://beautymarket.ma/products/revolution-fast-base-contour-stick-dark',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MakeupRevolutionFastBaseContourStickDark1_a4008efb-caa2-40a1-bcab-3ef41a955518.jpg?v=1753902837"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
