INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION ULTRA BLUSH PALETTE GOLDEN SUGAR','Revolution','Autres soins','Une palette de maquillage polyvalente conçue pour rehausser votre teint. Elle propose une sélection de teintes de fard à joues très pigmentées, des poudres illuminatrices et un bronzer, tous formulés pour convenir à une variété de tons de peau. La palette inclut généralement des finitions mates et iridescentes, vous permettant de créer une gamme de looks allant du naturel au glamour.

Avec son packaging élégant, elle est pratique pour des retouches en déplacement et convient aussi bien aux débutants qu''aux passionnés de maquillage. La palette Golden Sugar est particulièrement appréciée pour ses tons chauds et radieux qui apportent un éclat sain aux joues.',11500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UltraBlushPaletteGoldenSugar1_92750de4-a366-4b16-b8bc-3ddc0ef8bedb.jpg?v=1753902909',10,1,'8279632249007','45741357990063','https://beautymarket.ma/products/revolution-ultra-blush-palette-golden-sugar',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UltraBlushPaletteGoldenSugar1_92750de4-a366-4b16-b8bc-3ddc0ef8bedb.jpg?v=1753902909"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION ULTRA BLUSH PALETTE HOT SPICE','Revolution','Autres soins','La palette Ultra Blush Palette Hot Spice de Revolution Makeup est un incontournable pour les amateurs de blush. Elle comprend une sélection de teintes chaudes et épicées, allant des roses aux corails, idéales pour rehausser votre teint et apporter une touche de fraîcheur à votre maquillage.

Chaque couleur est pigmentée et se fond facilement sur la peau, permettant une application modulable, que vous souhaitiez un look naturel ou plus prononcé. La palette est dotée de plusieurs finis, allant du mat au satiné, pour répondre à toutes vos envies. Compacte et légère, elle est parfaite pour les déplacements et peut être utilisée pour le contouring, le blush ou même comme ombre à paupières.

Avec cette palette, vous aurez tous les outils nécessaires pour créer des looks diversifiés et chaleureux tout au long de l''année.',11500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UltraBlushPaletteHotSpice1_827be61b-93cc-4cd2-8325-9b83da7b4714.jpg?v=1753902911',10,1,'8279632314543','45741358055599','https://beautymarket.ma/products/revolution-ultra-blush-palette-hot-spice',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/UltraBlushPaletteHotSpice1_827be61b-93cc-4cd2-8325-9b83da7b4714.jpg?v=1753902911"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVOLUTION ULTRA CREAM BRONZER MEDIUM','Revolution','Autres soins','Vous voulez simuler un bronzage ensoleillé dans le confort de votre propre maison ? Découvrez la Revolution Ultra Cream Bronzer, une crème de contouring ultra-crémeuse et ultra-fusible.

Disponible en 3 teintes, vous pourrez instantanément vous transformer en une beauté bronzée :

Light

Medium

Dark

Comment utiliser:

Appliquez simplement la poudre bronzante sur vos pommettes, sur votre nez ou sur votre front pour ajouter un peu de chaleur ou ciseler cette mâchoire ! Restez SNATCHED !

Végétalien et sans cruauté envers les animaux',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_4_080b883d-b5d4-48d3-bfd0-498e879fd3ed.jpg?v=1753902913',10,1,'8279632380079','45741358284975','https://beautymarket.ma/products/revolution-ultra-cream-bronzer-medium',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1_4_080b883d-b5d4-48d3-bfd0-498e879fd3ed.jpg?v=1753902913"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revolution Big Lash Reloaded Mascara','Revolution','Autres soins','Le mascara Revolution Big Lash est LE mascara volumisant par excellence. Sa nouvelle formule et sa méga brosse offrent désormais à vos cils un effet super allongeant.

La grosse brosse fuselée a été spécialement conçue pour gainer chaque cil et leur donner un volume spectaculaire. Les picots courts s''accrochent à la racine des cils pour attraper même les plus petits cils et les chargent pour un effet volume intense. Les longs picots gainent chaque cil de la racine à la pointe pour un volume extra large couplé à un effet allongeant

La formule enrichie en pigments noirs intenses est légère et sèche rapidement. Le résultat ? Des cils incroyablement volumineux.',8500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1546942_1_18d08cd9-1873-4725-a54a-8bd365d4ac7a.jpg?v=1753902914',10,1,'8279632445615','45741358350511','https://beautymarket.ma/products/revolution-big-lash-reloaded-mascara',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1546942_1_18d08cd9-1873-4725-a54a-8bd365d4ac7a.jpg?v=1753902914"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
