INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revolution Duo Brow Definer Pencil Light Brown','Revolution','Maquillage','Découvrez la clé pour des sourcils impeccables avec le Duo Brow Definer de Revolution !

