INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Absolute New York WATERPROOF GEL EYELINER BLACK','Absolute New York','Autres soins','Crayon Contour Yeux Waterproof d''Absolute New York – Un crayon pour les yeux conçu pour offrir une tenue longue durée sans faille, même dans les conditions les plus extrêmes.

