INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Curaprox Waxed dental floss 50M DF 834','Curaprox','Hygiène','Fil dentaire ciré au goût mentholé. Son enrobage en cire : i) permet au fil de glisser dans les espaces interdentaires pour un nettoyage efficace ; ii) facilite sa manipulation, réduisant ainsi le risque de blessures gingivales.

