INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Jonzac Sublimactive Sérum concentré raffermissant 30 ml','Jonzac','Visage','Sérum raffermissant à absorption rapide qui lisse les rides, raffermit et repulpe la peau pour un effet liftant au quotidien. Les points forts : lisse les rides, raffermit et repulpe la peau, effet liftant au quotidien, préserve l’équilibre du microbiome, texture légère à absorption rapide. Gamme Sublimactive d’Eau Thermale Jonzac, formule haute tolérance fabriquée en France par les Laboratoires Léa Nature.

