INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Needly Cicachid Relief Cream 48 ml – Crème Apaisante & Réparatrice Peau Sensible','Needly','Visage','Calmez et réparez votre peau avec Needly Cicachid Relief Cream 48 ml. Sa formule riche en agents apaisants soulage les irritations et rougeurs, tout en renforçant la barrière cutanée. Adaptée aux peaux sensibles, cette crème apporte confort et douceur immédiats.

