INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Studio17 Makeup Spatula 1u – Spatule de Maquillage Professionnelle pour Mélange & Application Hygiénique','Studio17','Cheveux','Studio17 Makeup Spatula 1u

