INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Luvum Bamboo Hyaluronic Moisture Suncream 50ml – Crème Solaire Hydratante & Éclatante SPF50+ PA++++','Luvum','Solaires','Luvum Bamboo Hyaluronic Moisture Suncream 50ml

