INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Luvum Slow Aging Super Food Oil Serum 30ml – Sérum Huile Anti-Âge aux Superaliments & Antioxydants','Luvum','Cheveux','Luvum Slow Aging Super Food Oil Serum 30ml

