INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Luvum Volume Lip Serum 4g – Soin Repulpant & Hydratant pour des Lèvres Douces et Pulpeuses','Luvum','Cheveux','Luvum Volume Lip Serum 4g

