INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ZIAJA VITAMIN C.B3 NIACINAMIDE GEL NETTOYANT 190ML','Ziaja','Visage','ZIAJA C.B3 GEL NETTOYANT 190ML :

