INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ZIAJA EAU MICELLAIRE A L''OLIVE NATUREL 200ML','Ziaja','Visage','Prévient de la déshydratation et apaise les irritations. Adoucit la peau et tonifie l’épiderme.

