INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Seoul Glam Toner au Riz 150ml – Lotion Tonique Éclat & Hydratation pour Tous Types de Peau','Seoul Glam','Visage','Seoul Glam Toner au Riz 150ml

