INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Seoul Glam Huile Nettoyante au Riz 100ml – Démaquillant & Soin Nourrissant pour Peau Douce et Lumineuse','Seoul Glam','Visage','Seoul Glam Huile Nettoyante au Riz 100ml

