INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Seoul Glam Mousse Nettoyante Visage 200ml – Hydratante & Élimine les Impuretés','Seoul Glam','Visage','Seoul Glam Mousse Nettoyante Visage 200ml

