INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Alphanova Brumisateur d’eau Thermale HYDRA+ 300 ML','Alphanova','Visage','Brumisateur d’eau Thermale HYDRA+ Hydrate & Rafraîchit la peau

