INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Garnier Super UV Serum Sunscreen SPF50+ PA++++ – Peaux à Imperfections & Anti-Acné','Garnier','Solaires','Protégez votre peau tout en la traitant avec Garnier Super UV Acne Prone Skin Serum Sunscreen SPF50+ PA++++. Ce serum solaire visage à base de Salicylic BHA est spécialement conçu pour les peaux sujettes à l’acné, offrant une protection élevée contre les UVA/UVB tout en aidant à réguler les imperfections.

