INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ERAYBA GAMMA COLORATION HYDRATANTE 6/32','Erayba','Cheveux','Offrez à vos cheveux une couleur riche et lumineuse grâce à la teinte 6/32 (blond foncé / doré / irisé) de la gamme Erayba Gamma. Cette coloration professionnelle associe une couverture parfaite des cheveux blancs à un soin profond de la fibre capillaire.
