INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('La Roche-Posay Effaclar Patch Anti-Imperfections DUO+M – Patches Anti-Boutons & Anti-Acné','La Roche-Posay','Visage','Patchs anti-imperfections multi-actions : protège, cible, réduit.

