INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL PROFASHION BRONZER & HIGHLIGHTER SET SUN KISSED 01','Pastel','Solaires','Le set Pastel Profashion Bronzer & Highlighter vous apportera cette sensation de bronzage et de vacances tout au long de l’année. La poudre bronzante donne à votre peau un aspect bronzé et doré tout en conservant une apparence naturelle et saine. Le highlighter doux comme du satin offre une texture légère et brillante qui illumine les contours de votre visage. La pigmentation riche signifie qu’une petite quantité suffit.',5500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-bronzer-_-highlighter-set-sunkissed_01_1000x_1_1.jpg?v=1761834483',10,1,'8358108201135','46106604765359','https://beautymarket.ma/products/pastel-profashion-bronzer-highlighter-set-sun-kissed-01',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-bronzer-_-highlighter-set-sunkissed_01_1000x_1_1.jpg?v=1761834483"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
