INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL PROFASHION ARTLINER PEN 01','Pastel','Maquillage','Profashion Artliner Pen s’applique facilement grâce à son stylo à pointe feutrée et permet d’utiliser différentes méthodes d’eyeliner. Sa formule sans écailles ni bavures résiste à l’eau, à l’humidité et à la température, ce qui lui permet de conserver son effet pendant longtemps. Il garantit un regard d’un noir de jais et d’une profondeur parfaite, de jour comme de nuit. Idéal pour les yeux sensibles et/ou les utilisateurs de lentilles de contact.',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-artliner-pen_168_1000x_d7e14611-85e1-41d4-8712-dc158f9c007b.jpg?v=1761835905',10,1,'8358439059631','46106948468911','https://beautymarket.ma/products/pastel-profashion-artliner-pen-01',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-artliner-pen_168_1000x_d7e14611-85e1-41d4-8712-dc158f9c007b.jpg?v=1761835905","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/8690644010538-2_bznlnsbyso5l6ibq.jpg?v=1761835909","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-artliner-pen_168b_720x_4d56ad32-b95a-49fc-a9eb-f945ad439299.jpg?v=1761835906"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL EXPRESS VOLUME +LENGHT MASCARA','Pastel','Maquillage','Le mascara volume et longueur de Pastel donne à vos cils la nuance de noir la plus intense. Ses ingrédients spéciaux aident à réparer et à nourrir les cils. La structure flexible de la brosse en silicone est adaptée à la courbe de l’œil, ce qui lui permet d’attraper même les cils les plus courts et les plus fins et d’obtenir un effet longue durée. Fournit des nutriments à vos cils grâce au panthénol et à la vitamine E qu’il contient.',6900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-express-volume-_-length-mascara_180a_720x_48e27c3f-09df-4cea-8052-18b78c857b7e.jpg?v=1761837133',10,1,'8358599065775','46107112767663','https://beautymarket.ma/products/pastel-express-volume-lenght-mascara',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Pastel-cosmetics-uk-express-volume-_-length-mascara_180a_720x_48e27c3f-09df-4cea-8052-18b78c857b7e.jpg?v=1761837133"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PASTEL NUDE NAIL POLISH 767','Pastel','Maquillage','Application : Appliquer deux couches sur les ongles propres. Appliquer la première couche, puis la deuxième lorsque la première a partiellement séché.

Avantages :

1- Couverture des couleurs facile et rapide sur la première couche avec une couverture des couleurs supérieure.

2- Application facile et fluide en une seule fois grâce à sa formule spéciale

3- Grâce à son composé spécial résistant à l''abrasion, il contribue à améliorer le peeling de la surface de l''ongle et l''érosion des pointes de l''ongle.

4- Grâce à la brosse à plat spécialement coupée, elle saisit vos ongles de la meilleure façon et permet une application facile en une seule fois.',2500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pastel-nude-nail-polish-ref-767-mauve.webp?v=1761837510',10,1,'8358637338799','46107153334447','https://beautymarket.ma/products/pastel-nude-nail-polish-767',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/pastel-nude-nail-polish-ref-767-mauve.webp?v=1761837510"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
